@pytest.mark.parametrize("little, refusal", [(0.1, "over_room"), (0.0, "over_room")]) def test_a_standing_unfilled_rest_counts_against_the_day_on_the_next_tick( monkeypatch, little, refusal): """TWO TICKS. Tick 1: one book rests a BUY of $90 (300 @ 0.30) with the mirror's day room at $90 + `little`. Tick 2: that rest still stands unfilled, and a second book on a second market wants the same $90. It must be refused on the day cap -- `over_room`, _act's room scaling against t.mirror_day, whether a little room is left (not a share's worth) or none at all: the room counts the rest, the BLOCK does not (nothing filled), so the standing rest is never cancelled -- and nothing new may rest. Against the original _SQL_MIRROR_DAY the second book rests another 300 shares on tick 2 and this test fails: the fake pool reads the day columns from the statement's text.""" monkeypatch.setattr(rules, "MIRROR_DAY_USD", 90.0 + little) p, http = _two_markets() b1 = p.add_book(ledger=0) v = _Venue(bid=0.30, ask=0.32) st1 = _tick(p, v, http=http) pl = _places(v) # E31 (FILL lane 31, 2026-09-10): THE ENTRY'S CENT MOVED. A long entry no # longer JOINS THE BID at 0.30; it rests at the maker wire # min(buy_wire(his 0.31), ask 0.32 - MAKER_TICK) = 0.31, so every quantity # this file derives from a dollar room is that room divided by 0.31, not 0.30. # $90 + `little` at 0.31 is 290 shares, where 0.30 bought 300; the rail under # test is the DAY ROOM and the rest still spends all of it > assert len(pl) == 1 and pl[0][3] == 290 and pl[0][2] == 0.31 and pl[0][4] is False E assert (0 == 1) E + where 0 = len([])
