        elif arm == "clip":
            monkeypatch.setattr(le, "per_fill_usd", lambda *a, **k: 0.0)
        elif arm == "venue":
            v = _Venue(held={SLUG: 5})
        elif arm == "band":
            # FILL lane 0a: the rail's default (the env no longer reaches the worker; the constant does)
